onTaskEvent(onDoneOrDropped);
function newNotes(a) {
  const all = Array.isArray(a.notes) ? a.notes : [a.notes ?? a.note];
  const shared = typeof a.topic === "string" ? a.topic : "";
  const out = [];
  for (const x of all) {
    if (typeof x === "string") {
      if (x.trim())
        out.push({ text: x, topic: shared });
    } else if (x && typeof x === "object" && typeof x.text === "string" && x.text.trim()) {
      const t = x.topic;
      out.push({ text: x.text, topic: typeof t === "string" ? t : shared });
    }
  }
  return out;
}
async function orgMemTool(host, a) {
  if (!S.root)
    return "No project folder yet.";
  const file = orgMemFile(S.N.dir);
  const action = typeof a.action === "string" && a.action.trim() ? a.action.trim().toLowerCase() : "list";
  const date = now().slice(0, 10);
  const save = (text) => safeWrite(host, path(file), text, "the organizational memory (org-mem)");
  const which = typeof a.which === "number" || typeof a.which === "string" ? a.which : undefined;
  if (action === "list")
    return orgMemList(await readGuide(host), file);
  return oneAtATime(file, async () => {
    const old = await readGuide(host);
    if (action === "add") {
      const notes = newNotes(a);
      if (!notes.length)
        throw new Error("add needs notes: one or more {text, topic}");
      const r = orgMemAdd(old, notes, date);
      const parts = [];
      if (r.full)
        parts.push(`Not added: ${file} would go past ${ORG_MEM_MAX_LINES} lines. Remove or replace a note first (action list shows them).`);
      if (r.added.length) {
        await save(r.text);
        parts.push(`Added to ${file}: ${r.added.map((x) => `"${x}"`).join(", ")}.`);
      }
      if (r.repeats.length)
        parts.push(`Not added, already there (or close to a note there; use replace to improve it): ${r.repeats.map((x) => `"${x}"`).join(", ")}.`);
      if (r.bad.length)
        parts.push(`Not added (empty, looks secret or is file contents): ${r.bad.length}.`);
      if (r.noTopic.length)
        parts.push(`Not added, no good topic (${BAD_TOPIC}): ${r.noTopic.map((x) => `"${x}"`).join(", ")}.`);
      return parts.join(`
`);
    }
    if (action === "topic") {
      const from = typeof a.from === "string" && a.from.trim() ? a.from : undefined;
      const r = orgMemSetTopic(old, which, typeof a.topic === "string" ? a.topic : "", from, date);
      const missing = r.missing.length ? ` No note ${r.missing.join(", ")} (skipped).` : "";
      if (r.why)
        return `Topics not changed: ${r.why}.${missing}`;
      if (r.changed.length)
        await save(r.text);
      const t = cleanTopic(a.topic);
      return r.changed.length ? `Set topic "${t}" on ${r.changed.length === 1 ? "note" : "notes"} ${r.changed.map((x) => x.n).join(", ")} in ${file}.${missing}` : `Those notes already have topic "${t}": nothing changed.${missing}`;
    }
    if (which === undefined)
      throw new Error(`${action} needs which: the note's number (see action list) or its text`);
    if (action === "remove") {
      const r = orgMemRemove(old, which);
      if (!r.removed)
        return `No note ${JSON.stringify(which)} in ${file} (a number from action list, or the note's text): nothing removed.`;
      await save(r.text);
      return `Removed note ${r.removed.n} from ${file}: "${r.removed.text}".`;
    }
    if (action === "replace") {
      const by = typeof a.by === "string" ? a.by : typeof a.note === "string" ? a.note : "";
      const r = orgMemReplace(old, which, by, date, typeof a.topic === "string" ? a.topic : undefined);
      if (r.why)
        return `Not replaced: ${r.why}.`;
      await save(r.text);
      return `Replaced note ${r.old.n} in ${file}: "${r.old.text}" is now "${r.now}" [${r.topic}].`;
    }
    throw new Error(`action must be list, add, remove, replace or topic (got ${JSON.stringify(a.action)})`);
  });
}
