function startDebrief(host, agentId, task2, attempts, report = "") {
  const followUp = host.agents.followUp;
  if (!followUp || !agentId || debriefs.has(agentId))
    return;
  const d = { task: task2, attempts, timer: null, report: report.trim() };
  debriefs.set(agentId, d);
  try {
    d.timer = host.clock.after(DEBRIEF_MS, () => {
      if (debriefs.get(agentId) !== d)
        return;
      debriefs.delete(agentId);
      host.agents.stop(agentId, 'Stop now: no answer is needed any more. Change nothing; answer "stopped" and end.').catch(() => {
        return;
      });
    }) ?? null;
  } catch {
    d.timer = null;
  }
  if (!d.timer) {
    debriefs.delete(agentId);
    return;
  }
  const drop = () => {
    if (debriefs.get(agentId) !== d)
      return;
    debriefs.delete(agentId);
    d.timer?.cancel();
  };
  Promise.resolve().then(() => followUp(agentId, DEBRIEF_TEXT)).then((r) => {
    if (r && typeof r === "object" && r.isDelivered === false)
      drop();
  }).catch(drop);
}
