  const lead2 = parseLead(leadText2);
  if (lead2 && !isFresh(lead2.heartbeat, nowMs))
    listed.push({ kind: "board", fixable: false, text: `${S.N.leadFile} names a session that stopped ${Math.round((nowMs - lead2.heartbeat) / 60000)} min ago, so no session drives the board: /${S.N.name}-drive makes this one drive it` });
