  const recorded = taskCommits(t).map((c) => c.sha);
  const hasBranch = await branchExists($, branch);
  if (!hasBranch) {
    const last = recorded[0];
    if (!last)
      throw new Error(`${t.id} has no branch ${branch} and no recorded commits, so there is no work to find in ${into}`);
    if (!await inBranch($, last, `refs/heads/${into}`))
      throw new Error(`${t.id}'s last commit ${shortSha(last)} isn't in ${into} yet (its branch ${branch} is gone)`);
    return { sha: await mergeCommitOf($, last, into), commits: [...recorded].reverse() };
  }
  const tip = (await git($, ["rev-parse", "--verify", "-q", `refs/heads/${branch}`])).stdout.trim();
