  if (!own.length && !recorded.length)
    throw new Error(`${t.id}'s branch ${branch} has no commits of its own, so there is no work to find in ${into}`);
  if (!own.length) {
    const last = recorded[0];
    if (!await inBranch($, last, `refs/heads/${into}`))
      throw new Error(`${t.id}'s last commit ${shortSha(last)} isn't in ${into} yet (its branch ${branch} has no commits of its own)`);
    return { sha: await mergeCommitOf($, last, into), commits: [...recorded].reverse() };
  }
  if (await inBranch($, tip, `refs/heads/${into}`))
    return { sha: await mergeCommitOf($, tip, into), commits: own };
