  if (ch.exitCode !== 0)
    throw new Error(`git could not compare ${t.id}'s branch ${branch} with ${into}: ${(ch.stderr || ch.stdout).trim().slice(0, 200)}`);
  const lines = ch.stdout.split(`
`).map((l) => l.trim()).filter(Boolean);
  const missing = lines.filter((l) => l.startsWith("+")).length;
  if (missing || !lines.length)
    throw new Error(notMergedText(t.id, missing || 1, into));
