  const same2 = eq.exitCode === 0 ? eq.stdout.split(`
`).map((l) => l.trim()).find((l) => l.startsWith("=")) : undefined;
  const sha = same2?.slice(1);
  const head = (await git($, ["rev-parse", "--verify", "-q", `refs/heads/${into}`])).stdout.trim();
