  const L = [`${t.id}  [${word[t.status]}]  ${t.title}`, `added ${when2(t.created_at)} · changed ${when2(t.updated_at)} · tries ${t.attempts}`];
  L.push(fromText(t, 120));
  if (t.origin?.why)
    L.push(`why: ${t.origin.why}`);
  if (t.origin?.evidence)
    L.push(`seen by ${S.N.name}: ${t.origin.evidence}`);
  if (shownNote(t))
    L.push(`${stateLabelLower()}: ${shownNote(t)}`);
  if (t.status === "waiting" && t.ask?.text)
    L.push("", `ASKS: ${t.ask.text}`);
  if (t.status === "waiting" && t.ask?.options?.length)
    L.push(`OPTIONS: ${t.ask.options.join(" | ")}`);
  L.push("", "What to do:", ...t.details.trim() ? t.details.split(`
`).map((l) => l.trim() ? `  ${l}` : "") : ["  (no details)"]);
  L.push("", "May change:", ...t.files.length ? t.files.map((f) => `  ${f}`) : ["  anywhere in the project"]);
  L.push("", `merges into: ${intoOf(t)}`);
  if (t.after.length) {
    L.push("", "Waits for:");
    for (const id of t.after) {
      const dep = all.find((x) => x.id === id);
      L.push(`  ${id} ${dep ? `[${word[dep.status]}] ${dep.title}` : archivedDone.includes(id) ? `[${word.done}] (archived)` : "[missing]"}`);
    }
    for (const n of crossBranchNotes(t, all))
      L.push(`  note: ${n}`);
  }
  if (t.history.length)
    L.push("", `What happened (${t.history.length}, newest first):`, ...[...t.history].reverse().map((h) => `  • ${historyLineText(h)}`));
  if (t.runs?.length)
    L.push("", "Time and cost:", ...t.runs.map((r, i) => `  ${fmtRun(r, i, Date.now())}`), `  total: ${fmtTotal(sumRuns(t.runs, Date.now()))}`);
  const commits2 = taskCommits(t);
  if (commits2.length)
    L.push("", "Commits (newest first):", ...commits2.map((c) => `  ${commitText(c)}`));
  if (t.branch)
    L.push("", `branch: ${t.branch}`);
  if (t.research_notes?.length)
    L.push("", ...t.research_notes.map((f) => `Research: ${f}`));
  if (report === null && t.attempts > 0)
    L.push("", "Report: no saved report");
  if (report)
    L.push("", `Report (try ${report.try}, ${report.file}):`, ...report.text === null ? ["  (could not read the file)"] : reportPreview(report.text, report.file).map((l) => l ? `  ${l}` : ""));
