var BOARD_OPENED = "Board opened: ↑↓ to move, Enter to open, f to search, t tasks, s scouts, c settings.";
var boardOpened = () => S.W.backToBoard ? `${BOARD_OPENED} (${S.W.backToBoard} goes back to it.)` : BOARD_OPENED;
